1	import { existsSync, mkdirSync, readFileSync, readdirSync, statSync, writeFileSync } from "node:fs";
2	import { dirname, isAbsolute, join, resolve } from "node:path";
3	import { trace } from "./diagnostics.ts";
4	import { logger } from "./logger.ts";
5	import { appendMemory } from "./memory.ts";
6	
7	export interface ToolSpec {
8	  name: string;
9	  description: string;
10	  args: string;
11	  needsApproval: boolean;
12	  subagentSafe: boolean;
13	  run: (args: Record<string, unknown>) => Promise<string>;
14	}
15	
16	export type TodoStatus = "pending" | "in_progress" | "done";
17	
18	export interface TodoItem {
19	  text: string;
20	  status: TodoStatus;
21	}
22	
23	export interface ApprovalRequest {
24	  tool: string;
25	  summary: string;
26	  detail: string;
27	}
28	
29	const OUTPUT_CAP = 30_000;
30	
31	function cap(text: string): string {
32	  if (text.length <= OUTPUT_CAP) return text;
33	  return text.slice(0, OUTPUT_CAP) + `\n... [truncated, ${text.length - OUTPUT_CAP} more chars]`;
34	}
35	
36	function resolvePath(p: string): string {
37	  return isAbsolute(p) ? p : resolve(process.cwd(), p);
38	}
39	
40	function str(args: Record<string, unknown>, key: string, required = true): string {
41	  const v = args[key];
42	  if (typeof v === "string" && v.length > 0) return v;
43	  if (!required) return "";
44	  throw new Error(`missing required string argument "${key}"`);
45	}
46	
47	const SAFE_BASH_PREFIXES = [
48	  "ls", "cat ", "head ", "tail ", "grep ", "rg ", "find ", "pwd", "wc ", "which ",
49	  "echo ", "git status", "git log", "git diff", "git show", "git branch", "file ",
50	  "stat ", "du ", "df", "ps ", "env", "date", "uname", "tree", "sort ", "uniq ",
51	];
52	
53	export function isSafeBash(command: string): boolean {
54	  const trimmed = command.trim();
55	  if (/[;&|><`$]/.test(trimmed.replace(/\$\{?\w+\}?/g, ""))) {
56	    if (!/^[\w\s./*'"=-]+\|\s*(head|tail|wc|sort|uniq|grep)\b[\w\s./*'"-]*$/.test(trimmed)) {
57	      return false;
58	    }
59	  }
60	  return SAFE_BASH_PREFIXES.some((p) => trimmed === p.trim() || trimmed.startsWith(p));
61	}
62	
63	async function runBash(command: string, timeoutS: number): Promise<string> {
64	  const proc = Bun.spawn(["bash", "-c", command], {
65	    cwd: process.cwd(),
66	    stdout: "pipe",
67	    stderr: "pipe",
68	    env: { ...process.env, GIT_PAGER: "cat", PAGER: "cat" },
69	  });
70	  const timer = setTimeout(() => proc.kill(), timeoutS * 1000);
71	  const [out, err, code] = await Promise.all([
72	    new Response(proc.stdout).text(),
73	    new Response(proc.stderr).text(),
74	    proc.exited,
75	  ]);
76	  clearTimeout(timer);
77	  let result = out;
78	  if (err.trim()) result += (result ? "\n" : "") + `[stderr]\n${err}`;
79	  if (code !== 0) {
80	    result += `\n[exit code: ${code}]`;
81	    throw new Error(cap(result.trim()));
82	  }
83	  return cap(result.trim() || "(no output)");
84	}
85	
86	export interface BuildToolsOptions {
87	  onSubagent?: (task: string) => Promise<string>;
88	  onTodos?: (todos: TodoItem[]) => void;
89	}
90	
91	export function buildTools(opts: BuildToolsOptions): Map<string, ToolSpec> {
92	  const tools = new Map<string, ToolSpec>();
93	  const add = (t: ToolSpec) => tools.set(t.name, t);
94	
95	  add({
96	    name: "read_file",
97	    description: "Read a file. Returns numbered lines.",
98	    args: `{"path": string, "offset"?: number, "limit"?: number}`,
99	    needsApproval: false,
100	    subagentSafe: true,
101	    run: async (args) => {
102	      const path = resolvePath(str(args, "path"));
103	      if (!existsSync(path)) throw new Error(`file not found: ${path}`);
104	      const st = statSync(path);
105	      if (st.isDirectory()) throw new Error(`${path} is a directory — use ls`);
106	      if (st.size > 2_000_000) throw new Error(`file too large (${st.size} bytes)`);
107	      const lines = readFileSync(path, "utf8").split("\n");
108	      const offset = Number(args.offset ?? 1);
109	      const limit = Number(args.limit ?? 1500);
110	      const slice = lines.slice(offset - 1, offset - 1 + limit);
111	      const numbered = slice.map((l, i) => `${String(offset + i).padStart(5)}| ${l}`).join("\n");
112	      const more = lines.length > offset - 1 + limit ? `\n... [${lines.length} lines total]` : "";
113	      return cap(numbered + more);
114	    },
115	  });
116	
117	  add({
118	    name: "write_file",
119	    description: "Create or overwrite a file with the given content. Parent dirs are created.",
120	    args: `{"path": string, "content": string}`,
121	    needsApproval: true,
122	    subagentSafe: false,
123	    run: async (args) => {
124	      const path = resolvePath(str(args, "path"));
125	      const content = typeof args.content === "string" ? args.content : "";
126	      mkdirSync(dirname(path), { recursive: true });
127	      const existed = existsSync(path);
128	      writeFileSync(path, content);
129	      return `${existed ? "overwrote" : "created"} ${path} (${content.length} chars)`;
130	    },
131	  });
132	
133	  add({
134	    name: "edit_file",
135	    description:
136	      "Replace an exact string in a file. old_string must match exactly once (set all=true to replace every occurrence).",
137	    args: `{"path": string, "old_string": string, "new_string": string, "all"?: boolean}`,
138	    needsApproval: true,
139	    subagentSafe: false,
140	    run: async (args) => {
141	      const path = resolvePath(str(args, "path"));
142	      if (!existsSync(path)) throw new Error(`file not found: ${path}`);
143	      const oldStr = str(args, "old_string");
144	      const newStr = typeof args.new_string === "string" ? args.new_string : "";
145	      const content = readFileSync(path, "utf8");
146	      const count = content.split(oldStr).length - 1;
147	      if (count === 0) {
148	        const firstLine = oldStr.split("\n")[0].trim();
149	        const near = firstLine
150	          ? content
151	              .split("\n")
152	              .map((l, i) => ({ l, i }))
153	              .filter(({ l }) => firstLine.length > 3 && l.includes(firstLine.slice(0, Math.min(30, firstLine.length))))
154	              .slice(0, 3)
155	              .map(({ l, i }) => `${i + 1}| ${l}`)
156	              .join("\n")
157	          : "";
158	        throw new Error(
159	          `old_string not found in ${path}. It must match the CURRENT file content exactly, whitespace included.${near ? ` Nearby lines that partially match:\n${near}\n` : " "}Re-read the file first — or if this keeps failing, rewrite the whole file with write_file instead.`,
160	        );
161	      }
162	      if (count > 1 && !args.all)
163	        throw new Error(`old_string matches ${count} times — make it unique or pass "all": true`);
164	      const next = args.all ? content.split(oldStr).join(newStr) : content.replace(oldStr, newStr);
165	      writeFileSync(path, next);
166	      return `edited ${path} (${count} replacement${count > 1 ? "s" : ""})`;
167	    },
168	  });
169	
170	  add({
171	    name: "ls",
172	    description: "List a directory with entry sizes.",
173	    args: `{"path"?: string}`,
174	    needsApproval: false,
175	    subagentSafe: true,
176	    run: async (args) => {
177	      const path = resolvePath(typeof args.path === "string" && args.path ? args.path : ".");
178	      const entries = readdirSync(path)
179	        .filter((e) => e !== "node_modules" && e !== ".git")
180	        .slice(0, 300)
181	        .map((e) => {
182	          try {
183	            const st = statSync(join(path, e));
184	            return st.isDirectory() ? `${e}/` : `${e} (${st.size}b)`;
185	          } catch {
186	            return e;
187	          }
188	        });
189	      return cap(entries.join("\n") || "(empty)");
190	    },
191	  });
192	
193	  add({
194	    name: "glob",
195	    description: "Find files matching a glob pattern (e.g. **/*.ts), newest first.",
196	    args: `{"pattern": string, "path"?: string}`,
197	    needsApproval: false,
198	    subagentSafe: true,
199	    run: async (args) => {
200	      const root = resolvePath(typeof args.path === "string" && args.path ? args.path : ".");
201	      const glob = new Bun.Glob(str(args, "pattern"));
202	      const hits: Array<{ p: string; m: number }> = [];
203	      for await (const file of glob.scan({ cwd: root, dot: false })) {
204	        if (file.includes("node_modules/") || file.startsWith(".git/")) continue;
205	        try {
206	          hits.push({ p: file, m: statSync(join(root, file)).mtimeMs });
207	        } catch {
208	          hits.push({ p: file, m: 0 });
209	        }
210	        if (hits.length >= 500) break;
211	      }
212	      hits.sort((a, b) => b.m - a.m);
213	      return cap(hits.map((h) => h.p).join("\n") || "(no matches)");
214	    },
215	  });
216	
217	  add({
218	    name: "grep",
219	    description: "Search file contents with a regex (ripgrep). Returns file:line:text matches.",
220	    args: `{"pattern": string, "path"?: string, "glob"?: string}`,
221	    needsApproval: false,
222	    subagentSafe: true,
223	    run: async (args) => {
224	      const pattern = str(args, "pattern");
225	      const path = resolvePath(typeof args.path === "string" && args.path ? args.path : ".");
226	      const globFlag = typeof args.glob === "string" && args.glob ? ["--glob", args.glob] : [];
227	      const hasRg = Bun.which("rg") !== null;
228	      const cmd = hasRg
229	        ? ["rg", "-n", "--max-count", "50", "--max-columns", "300", ...globFlag, "-e", pattern, path]
230	        : ["grep", "-rn", "-m", "50", "-E", pattern, path];
231	      const proc = Bun.spawn(cmd, { stdout: "pipe", stderr: "pipe" });
232	      const [out, code] = await Promise.all([new Response(proc.stdout).text(), proc.exited]);
233	      if (code > 1) throw new Error(`search failed (exit ${code})`);
234	      return cap(out.trim() || "(no matches)");
235	    },
236	  });
237	
238	  add({
239	    name: "bash",
240	    description:
241	      "Run a shell command in the working directory. Output is captured. Use for builds, tests, git, installs.",
242	    args: `{"command": string, "timeout_s"?: number}`,
243	    needsApproval: true,
244	    subagentSafe: true,
245	    run: async (args) => {
246	      const command = str(args, "command");
247	      const timeout = Math.min(Number(args.timeout_s ?? 120), 600);
248	      return runBash(command, timeout);
249	    },
250	  });
251	
252	  add({
253	    name: "web_search",
254	    description:
255	      "Search the live web and get a synthesized answer with sources. Use for current events, docs, or anything outside your knowledge.",
256	    args: `{"query": string}`,
257	    needsApproval: false,
258	    subagentSafe: true,
259	    run: async (args) => {
260	      const query = str(args, "query");
261	      const { chat } = await import("./groq.ts");
262	      const { SUBAGENT_MODEL } = await import("./config.ts");
263	      const res = await chat(
264	        [
265	          {
266	            role: "user",
267	            content: `Search the web and answer concisely with source URLs: ${query}`,
268	          },
269	        ],
270	        { model: SUBAGENT_MODEL, enabledTools: ["web_search", "visit_website"], maxTokens: 2048 },
271	      );
272	      return cap(res.content);
273	    },
274	  });
275	
276	  add({
277	    name: "remember",
278	    description:
279	      "Persist a fact to long-term memory (~/.glint/memory.md). Use for durable user preferences or project facts worth keeping across sessions.",
