import { existsSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { DIRS, ensureDirs } from "./config.ts";

/**
 * Domain knowledge blocks: reusable expertise the weak base model lacks.
 * Each block declares trigger words/regexes; when the user's message matches,
 * the block's body is injected into the system prompt for that turn only — so
 * non-matching tasks stay lean. The agent can author new blocks at runtime via
 * the create_knowledge tool, accumulating expertise across sessions.
 */
export interface KnowledgeBlock {
  name: string;
  triggers: string[];
  body: string;
}

function parseTriggers(line: string): string[] {
  return line
    .split(",")
    .map((t) => t.trim())
    .filter((t) => t.length > 0);
}

export function loadKnowledge(name: string): KnowledgeBlock | null {
  const path = join(DIRS.knowledge, `${name}.md`);
  if (!existsSync(path)) return null;
  const raw = readFileSync(path, "utf8");
  const fm = raw.match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/);
  let triggers: string[] = [];
  let body = raw;
  if (fm) {
    const line = fm[1].split("\n").find((l) => l.startsWith("triggers:"));
    triggers = line ? parseTriggers(line.slice("triggers:".length)) : [];
    body = fm[2].trim();
  }
  return { name, triggers, body };
}

export function listKnowledge(): KnowledgeBlock[] {
  seedKnowledge();
  try {
    return readdirSync(DIRS.knowledge)
      .filter((f) => f.endsWith(".md"))
      .map((f) => loadKnowledge(f.replace(/\.md$/, "")))
      .filter((b): b is KnowledgeBlock => b !== null);
  } catch {
    return [];
  }
}

/** Return the knowledge blocks whose triggers match the user's message. */
export function matchKnowledge(userMessage: string): KnowledgeBlock[] {
  const text = userMessage.toLowerCase();
  return listKnowledge().filter((block) =>
    block.triggers.some((trigger) => {
      const t = trigger.toLowerCase();
      try {
        // A trigger may be a plain word or a small regex; treat word boundaries
        // for simple alphanumeric triggers, raw regex otherwise.
        if (/^[a-z0-9 -]+$/.test(t)) return new RegExp(`\\b${t.replace(/[-/\\^$*+?.()|[\]{}]/g, "\\$&")}\\b`).test(text);
        return new RegExp(t, "i").test(userMessage);
      } catch {
        return text.includes(t);
      }
    }),
