  ensureDirs();
  const safe = name.toLowerCase().replace(/[^a-z0-9-]/g, "-");
  const path = join(DIRS.knowledge, `${safe}.md`);
  writeFileSync(path, `---\ntriggers: ${triggers}\n---\n\n${body}\n`, { mode: 0o600 });
  return safe;
}

