 * specific "your block didn't parse" signal instead of "you ran zero tools".
 */
export function hasUnparsedToolBlock(text: string): boolean {
  const opened = text.includes(TOOL_OPEN) || /<<<glint:tool/.test(text);
  return opened && parseToolCalls(text).length === 0;
}

export function stripToolBlocks(text: string): string {
  return text
    .replace(XML_RE, "")
    .replace(SENTINEL_RE, "")
    .replace(/```\s*\n?\s*```/g, "")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

const OPENERS = ["<glint:tool>", "<<<glint:tool"];

