  // Whitespace-tolerant fallback: a weak model often reconstructs
  // old_string with slightly wrong indentation or trailing spaces. Match
  // with flexible whitespace runs, but only act on a UNIQUE hit so we
  // never edit the wrong place.
  const flexible = oldStr
    .trim()
    .replace(/[.*+?^${}()|[\]\\]/g, "\\$&")
    .replace(/\s+/g, "\\s+");
  let matches: RegExpExecArray[] = [];
  try {
    const re = new RegExp(flexible, "g");
    for (let m = re.exec(content); m !== null; m = re.exec(content)) {
      matches.push(m);
      if (matches.length > 1) break;
    }
  } catch {
    matches = [];
  }
  if (matches.length === 1) {
    const m = matches[0];
    const next = content.slice(0, m.index) + newStr + content.slice(m.index + m[0].length);
    writeFileSync(path, next);
    return `edited ${path} (1 replacement, whitespace-normalized match)`;
  }
  const firstLine = oldStr.split("\n")[0].trim();

