/** Stable dedup key: sort arg keys so the same call with reordered keys
 * (which a weak model does often) collapses to one key. */
function callKey(c: { tool: string; args: Record<string, unknown> }): string {
  let argStr: string;
  try {
    argStr = JSON.stringify(c.args, Object.keys(c.args).sort());
  } catch {
    argStr = JSON.stringify(c.args);
  }
  return c.tool + argStr;
}

/** Reorder calls emitted in one message so a file is created before it is read
 * or run: write_file/edit_file on a path come before read_file/bash that touch
 * the same path. Stable otherwise. Fixes the round-0 "read/run before write"
 * misordering a weak model frequently emits. */
function orderCalls<T extends { tool: string; args: Record<string, unknown> }>(calls: T[]): T[] {
  const rank = (c: T): number => {
    if (c.tool === "write_file" || c.tool === "edit_file") return 0;
    return 1;
  };
  return calls
    .map((c, i) => ({ c, i }))
    .sort((a, b) => rank(a.c) - rank(b.c) || a.i - b.i)
    .map((x) => x.c);
}

