/** Reorder calls emitted in one message so a file is created before it is read
 * or run. Only kicks in when a read_file/bash in the batch references a path
 * that a write_file/edit_file in the same batch creates — then writes go first.
 * Otherwise order is untouched. Fixes the round-0 "read/run before write"
 * misordering a weak model frequently emits, without disturbing unrelated ops. */
function orderCalls<T extends { tool: string; args: Record<string, unknown> }>(calls: T[]): T[] {
  const written = new Set<string>();
  for (const c of calls) {
    if ((c.tool === "write_file" || c.tool === "edit_file") && typeof c.args.path === "string") {
      written.add(c.args.path);
    }
  }
  if (written.size === 0) return calls;
  const refsWritten = calls.some(
    (c) =>
      (c.tool === "read_file" && typeof c.args.path === "string" && written.has(c.args.path)) ||
      (c.tool === "bash" &&
        typeof c.args.command === "string" &&
        [...written].some((p) => (c.args.command as string).includes(p))),
  );
  if (!refsWritten) return calls;
  const rank = (c: T): number => (c.tool === "write_file" || c.tool === "edit_file" ? 0 : 1);
  return calls
    .map((c, i) => ({ c, i }))
    .sort((a, b) => rank(a.c) - rank(b.c) || a.i - b.i)
    .map((x) => x.c);
}

