import { parseToolCalls, hasUnparsedToolBlock } from "./src/core/protocol.ts";

let pass = 0, fail = 0;
function check(name: string, cond: boolean) {
  if (cond) { pass++; console.log("  ok  " + name); }
  else { fail++; console.log("FAIL  " + name); }
}

// 1. Fenced content with unescaped quotes + newlines + braces (the #1 killer)
const fenced = `<glint:tool>
{"tool": "write_file", "args": {"path": "i.html"}}
---content---
<!doctype html>
<h1 class="t">Hello, "world" {x}</h1>
function f(){ return {a:1}; }
---end---
</glint:tool>`;
let c = parseToolCalls(fenced);
check("fenced parses", c.length === 1 && c[0].tool === "write_file");
check("fenced path kept", c[0]?.args.path === "i.html");
check("fenced content verbatim", String(c[0]?.args.content).includes('class="t"') && String(c[0]?.args.content).includes("{x}"));

// 2. edit_file with two fenced fields
const edit = `<glint:tool>
{"tool":"edit_file","args":{"path":"a.js"}}
---old_string---
const x = "hi"
---new_string---
const x = "bye"
---end---
</glint:tool>`;
c = parseToolCalls(edit);
check("edit fenced fields", c[0]?.args.old_string === 'const x = "hi"' && c[0]?.args.new_string === 'const x = "bye"');

// 3. trailing comma tolerance
c = parseToolCalls(`<glint:tool>\n{"tool":"read_file","args":{"path":"a.ts",}}\n</glint:tool>`);
check("trailing comma", c.length === 1 && c[0].args.path === "a.ts");

// 4. single quotes
c = parseToolCalls(`<glint:tool>\n{'tool':'ls','args':{'path':'src'}}\n</glint:tool>`);
check("single quotes", c.length === 1 && c[0].tool === "ls");

// 5. legit plain JSON still works
c = parseToolCalls(`<glint:tool>\n{"tool":"read_file","args":{"path":"x"}}\n</glint:tool>`);
check("plain json", c.length === 1);

// 6. unparsed-block detection: raw literal newline in JSON string (no fence)
const broken = `<glint:tool>\n{"tool":"write_file","args":{"path":"a","content":"line1\nline2"}}\n</glint:tool>`;
check("broken detected as unparsed", hasUnparsedToolBlock(broken));

// 7. no false positive on clean text
check("clean text not flagged", !hasUnparsedToolBlock("just a normal answer, no tools"));

console.log(`\n${pass} passed, ${fail} failed`);
if (fail) process.exit(1);
EOF
