// Auto-mode: a quick classifier (llama-3.1-8b-instant) decides how much tool
// access this request actually needs, so the model isn't tempted to misuse
// tools — e.g. reading files to answer a greeting. Three levels:
//   CHAT  — answerable as plain conversation → no tools at all
//   READ  — needs to inspect files but changes nothing → read-only tools
//   WRITE — creates/edits files or runs commands → all tools
// The model's own judgment makes the call (no keyword lists); fail-open to
// WRITE if the classifier errors.
let autoModeReadOnly = false;
let autoModeConversational = false;
if (config.auto) {
  try {
    const pre = await chat(
      [
        {
          role: "system",
          content:
            "Classify the user's message by how much access it needs to be answered well. Reply with ONE word:\nCHAT — it can be fully answered as plain conversation (a greeting, small talk, a general question, an explanation from your own knowledge); nothing on the user's machine needs to be looked at or changed.\nREAD — answering it well requires inspecting the user's files/code/project, but nothing should be created, edited, or executed.\nWRITE — it asks you to create, edit, build, install, run, or otherwise change files or execute commands.\nWhen unsure between two, pick the more capable one. Output only CHAT, READ, or WRITE.",
        },
        { role: "user", content: userMessage.slice(0, 2000) },
      ],
      { model: "llama-3.1-8b-instant", maxTokens: 8, temperature: 0 },
    );
    const verdict = pre.content.trim().toUpperCase();
    if (/\bCHAT\b/.test(verdict)) {
      autoModeConversational = true;
      cb.onNotice?.("auto-mode: conversational — replying directly, no tools");
    } else if (/\bREAD\b/.test(verdict)) {
      autoModeReadOnly = true;
      cb.onNotice?.("auto-mode: read-only request — answering in-chat (no file writes or commands)");
    }
  } catch (e) {
    // If the pre-check fails, allow tools (fail-open).
    trace("auto.precheck_failed", { error: String(e) });
  }
}

