export function buildSystemPrompt(opts: {
  tools: Map<string, ToolSpec>;
  effort: Effort;
  subagent?: boolean;
  knowledge?: KnowledgeBlock[];
  conversational?: boolean;
}): string {
  const memory = opts.subagent ? "" : readMemory();

  // Conversational turn: there are no tools this turn, so do NOT describe a tool
  // protocol — otherwise the model tries to call tools that don't exist and
  // flails. Keep it a lean, plain chat prompt.
  if (opts.conversational) {
    const chat = [
      `You are Glint, a coding agent by Glint Research, talking with the user in their terminal. You are NOT ChatGPT and were NOT made by OpenAI; if asked who you are, you are Glint.`,
      `This is a conversational turn — no tools are available and none are needed. Answer the user directly from your own knowledge, in a few sentences. Do NOT attempt to read files, run commands, or call tools, and do NOT describe doing so. If the user later asks for real work on their machine, you'll get tools then.`,
    ];
    if (memory) chat.push(`## Memory (persisted across sessions)\n${memory}`);
    return chat.join("\n\n");
  }

  const toolDocs = [...opts.tools.values()]
    .map((t) => `- ${t.name} ${t.args}\n  ${t.description}`)
    .join("\n");
  const effort = EFFORT_LEVELS[opts.effort];
  const skills = opts.subagent ? [] : listSkills();
  const project = opts.subagent ? "" : projectContext();

  const sections: string[] = [];

