// Autonomous multi-turn driver: drives runTurn with a persistent state like the
// TUI, so we can reproduce context-dependent behavior ("what was my last message").
import { newAgentState, runTurn } from "/home/lane/GR/glint-cli/src/core/agent.ts";
import { loadConfig } from "/home/lane/GR/glint-cli/src/core/config.ts";

const turns = process.argv.slice(2);
if (turns.length === 0) {
  console.error("usage: bun glintdrive.ts 'msg1' 'msg2' ...");
  process.exit(1);
}

const state = newAgentState();
const cfg = loadConfig();

for (const msg of turns) {
  console.log(`\n\x1b[36m❯ ${msg}\x1b[0m`);
  let finalText = "";
  const toolCalls: string[] = [];
  const notices: string[] = [];
  await runTurn(
    state,
    msg,
    cfg.effort === "ultracode" ? "max" : cfg.effort,
    {
      onAssistantText: (t) => {
        finalText = t;
      },
      onToolStart: (tool, args) => {
        const hint = (args.path ?? args.command ?? args.query ?? args.pattern ?? "") as string;
        toolCalls.push(`${tool} ${String(hint).slice(0, 60)}`);
      },
      onToolEnd: (tool, status) => {
        if (status === "error") toolCalls[toolCalls.length - 1] += "  [ERROR]";
      },
      onApproval: async () => true,
      onNotice: (t) => notices.push(t),
    },
  );
  for (const n of notices) console.log(`  \x1b[2m! ${n}\x1b[0m`);
  for (const tc of toolCalls) console.log(`  \x1b[33m⏺ ${tc}\x1b[0m`);
  console.log(`  \x1b[32m✦\x1b[0m ${finalText.replace(/\n/g, "\n    ")}`);
  console.log(`  \x1b[2m[history: ${state.messages.length} msgs, ${state.totalUsage.total_tokens} tok total]\x1b[0m`);
}

