import { API_URL, GROQ_API_KEY } from "./config.ts";
import { trace } from "./diagnostics.ts";
import { logger } from "./logger.ts";
import { TOOL_CLOSE, TOOL_OPEN, parseToolCalls } from "./protocol.ts";

// Once the model has emitted a complete tool call, anything more it generates
// this round is a wasted draft answer (the churn the user sees). Detect a
// finished call in EITHER channel and stop generating immediately — compound
// often "acts" in the reasoning channel while drafting prose in content, so we
// must watch both. The content channel may legitimately hold consecutive tool
// blocks, so we only stop on content once non-block prose follows the last one.
function maybeHasClose(text: string): boolean {
  return text.includes(TOOL_CLOSE) || /(^|\n)\s*>>>/.test(text);
}

function shouldEarlyStop(content: string, reasoning: string): boolean {
  if (reasoning && maybeHasClose(reasoning) && parseToolCalls(reasoning).length > 0) return true;
  if (!maybeHasClose(content)) return false;
  if (parseToolCalls(content).length === 0) return false;
  const i = content.lastIndexOf(TOOL_CLOSE);
  const tail = (i === -1 ? "" : content.slice(i + TOOL_CLOSE.length)).trim();
  if (tail === "") return false; // maybe another block is still coming
  if (tail.startsWith(TOOL_OPEN) || TOOL_OPEN.startsWith(tail)) return false; // next block
  return true; // prose after a finished call → stop now
}

