import { newAgentState, runTurn } from "/home/lane/GR/glint-cli/src/core/agent.ts";
import { loadConfig } from "/home/lane/GR/glint-cli/src/core/config.ts";

const state = newAgentState();
const cfg = loadConfig();
for (const msg of process.argv.slice(2)) {
  console.log(`\n\x1b[36m❯ ${msg}\x1b[0m`);
  let finalText = "";
  let roundContent = "";
  let maxBetweenTool = 0;
  const events: string[] = [];
  await runTurn(state, msg, cfg.effort === "ultracode" ? "max" : cfg.effort, {
    onDelta: (d, ch) => { if (ch === "content") roundContent += d; },
    onAssistantText: (t) => { finalText = t; },
    onToolStart: (tool, args) => {
      // content accumulated since last tool/answer = the between-tool draft
      const between = roundContent.trim().length;
      if (between > maxBetweenTool) maxBetweenTool = between;
      events.push(`⏺ ${tool} ${String(args.path ?? args.command ?? args.query ?? "").slice(0,50)}  (content before this call: ${between} chars)`);
      roundContent = "";
    },
    onToolEnd: (_t, s) => { if (s === "error") events[events.length-1] += " [ERR]"; },
    onApproval: async () => true,
    onNotice: (t) => events.push(`! ${t}`),
  });
  for (const e of events) console.log("  " + e);
  console.log(`  \x1b[32m✦ FINAL:\x1b[0m ${finalText.slice(0,300).replace(/\n/g," ")}`);
  console.log(`  \x1b[33m>>> max content generated before any tool call this turn: ${maxBetweenTool} chars\x1b[0m`);
  console.log(`  [${state.totalUsage.total_tokens} tok total]`);
}

