// Background-agent tools only exist at high+ effort: on simple tasks the weak
// model otherwise reaches for spawn_agent/await_agents unprompted.
const allowBackgroundAgents = effort === "high" || effort === "max" || effort === "ultracode";
const tools = buildTools({
  onSubagent: (task) => runSubagent(task, signal),
  onTodos: cb.onTodos ?? (() => {}),
  allowBackgroundAgents,
});

// If auto-mode decided no tool use is needed, filter out write/edit/bash;
// if it judged the request purely conversational, remove ALL tools so the
// model answers directly instead of "investigating" by reading files.
const effectiveTools: Map<string, ToolSpec> = autoModeConversational
  ? new Map<string, ToolSpec>()
  : autoModeReadOnly
    ? new Map([...tools].filter(([, t]) => !t.needsApproval))
    : tools;

// Inject any domain-knowledge blocks whose triggers match this request.
const knowledge = autoModeReadOnly || autoModeConversational ? [] : matchKnowledge(userMessage);
if (knowledge.length > 0)
  trace("turn.knowledge", { blocks: knowledge.map((k) => k.name) });

// If tools were filtered, also restrict the agent's system prompt.
const system = buildSystemPrompt({
  tools: effectiveTools,
  effort,
  knowledge,
  conversational: autoModeConversational,
});
const maxIterations = EFFORT_LEVELS[effort].maxIterations;

state.messages.push({ role: "user", content: userMessage });
trace("turn.user", { chars: userMessage.length, effort, autoMode: config.auto });
logger.info("turn.start", { effort, history: state.messages.length, autoMode: config.auto });

const turnExecuted = new Set<string>();

