// Conversational turns are a quick chat — cap output hard so the model can't
// dump a multi-table essay (and burn tens of thousands of tokens) on "what is
// X". A web_search call + a short grounded answer fit easily under this.
const roundMaxTokens = autoModeConversational ? 1024 : DEFAULT_MAX_TOKENS;

