export interface BuildToolsOptions {
  onSubagent?: (task: string, signal?: AbortSignal) => Promise<string>;
  onTodos?: (todos: TodoItem[]) => void;
  /** Background-agent tools (spawn_agent/await_agents) are only registered when
   * true — the weak model otherwise hallucinates await_agents on trivial tasks. */
  allowBackgroundAgents?: boolean;
  /** Receives a cleanup fn that aborts any background agents still running, so
   * the caller can drain them when the turn ends (otherwise a spawned-but-never-
   * awaited agent keeps making API calls forever). */
  registerCleanup?: (cleanup: () => void) => void;
}

export function buildTools(opts: BuildToolsOptions): Map<string, ToolSpec> {
  const tools = new Map<string, ToolSpec>();
  const add = (t: ToolSpec) => tools.set(t.name, t);
  // Per-buildTools (i.e. per-turn) background-agent registry. Keeping this
  // local — not module-global — means agents from one turn can't leak into the
  // next turn's await_agents, and they're dropped when the turn's tools are.
  let spawnCounter = 0;
