// Verify: a background agent spawned but never awaited is aborted when the turn ends.
import { buildTools } from "/home/lane/GR/glint-cli/src/core/tools.ts";

let aborted = false;
let started = false;
const cleanups: Array<()=>void> = [];
const tools = buildTools({
  allowBackgroundAgents: true,
  registerCleanup: (fn) => cleanups.push(fn),
  // simulate a long-running subagent that resolves only if not aborted
  onSubagent: (task, signal) => new Promise<string>((resolve, reject) => {
    started = true;
    const timer = setTimeout(() => resolve("done"), 5000);
    signal?.addEventListener("abort", () => { aborted = true; clearTimeout(timer); reject(new Error("aborted")); });
  }),
});

// model spawns an agent but never awaits it
const spawn = tools.get("spawn_agent")!;
const r = await spawn.run({ task: "leak me" });
console.log("spawn result:", r.slice(0, 40));
console.log("agent started:", started);
// turn ends -> cleanup runs
for (const fn of cleanups) fn();
await new Promise(r => setTimeout(r, 50));
console.log("agent aborted on turn end:", aborted, aborted ? "✓ no leak" : "✗ LEAKED");
process.exit(aborted ? 0 : 1);
EOF
