// Headless-render quality gate for a generated HTML file (no npm deps — drives
// system Chrome over CDP). Checks: page loads with NO uncaught JS errors / no
// console.error, and at least one element actually has a computed animation or
// transition wired up (not just CSS text present). Exit 0 = pass.
import { spawn } from "node:child_process";
import http from "node:http";
import { readFileSync } from "node:fs";

const file = process.argv[2];
const CHROME = ["/usr/bin/google-chrome-stable", "/snap/bin/chromium", "/usr/bin/chromium-browser"].find((p) => {
  try { readFileSync(p); return true; } catch { return false; }
});
if (!CHROME) { console.error("no chrome"); process.exit(3); }
const port = 9700 + Math.floor((Date.now() % 200));
const chrome = spawn(CHROME, [
  "--headless=new", "--disable-gpu", "--no-sandbox", `--remote-debugging-port=${port}`,
  "--no-first-run", "--user-data-dir=/tmp/glintstress/.chrome-" + port,
]);
const fail = (m, c = 1) => { console.error(m); try { chrome.kill(); } catch {} process.exit(c); };

const get = (path) => new Promise((res, rej) => {
  http.get(`http://127.0.0.1:${port}${path}`, (r) => { let d = ""; r.on("data", (c) => d += c); r.on("end", () => res(d)); }).on("error", rej);
});
const cdp = (ws) => new Promise((res, rej) => {
  import("node:http").then(() => {});
  const WebSocket = globalThis.WebSocket;
  const sock = new WebSocket(ws);
  const pending = new Map(); let id = 0; const errors = [];
  sock.onmessage = (e) => {
    const m = JSON.parse(e.data);
    if (m.id && pending.has(m.id)) { pending.get(m.id)(m.result); pending.delete(m.id); }
    if (m.method === "Runtime.consoleAPICalled" && m.params.type === "error") errors.push("console.error");
    if (m.method === "Runtime.exceptionThrown") errors.push("exception");
  };
  const send = (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); sock.send(JSON.stringify({ id: i, method, params })); });
  sock.onopen = async () => {
    await send("Runtime.enable"); await send("Page.enable");
    const url = "file://" + process.cwd() + "/" + file;
    await send("Page.navigate", { url });
    await new Promise((r) => setTimeout(r, 1500));
    const animed = await send("Runtime.evaluate", {
      expression: `[...document.querySelectorAll('*')].filter(e=>{const s=getComputedStyle(e);return s.animationName!=='none'||s.transitionDuration!=='0s'}).length`,
      returnByValue: true,
    });
    const sections = await send("Runtime.evaluate", {
      expression: `document.querySelectorAll('section,header,main,article,nav,footer').length`,
      returnByValue: true,
    });
    res({ errors, animed: animed?.value ?? 0, sections: sections?.value ?? 0 });
    sock.close();
  };
  sock.onerror = rej;
});

(async () => {
  // wait for chrome devtools endpoint
  let ws;
  for (let i = 0; i < 40; i++) {
    try { const j = JSON.parse(await get("/json/version")); ws = j.webSocketDebuggerUrl; break; } catch { await new Promise((r) => setTimeout(r, 250)); }
  }
  if (!ws) fail("chrome devtools never came up", 3);
  const r = await cdp(ws).catch((e) => fail("cdp error: " + e, 3));
  chrome.kill();
  console.log(JSON.stringify(r));
  if (r.errors.length) fail("JS errors on load: " + r.errors.join(","));
  if (r.animed < 1) fail("no element actually animates/transitions");
  if (r.sections < 2) fail("too few structural sections (" + r.sections + ")");
  console.log("RENDER-OK");
  process.exit(0);
})();

