async function runBash(command: string, timeoutS: number): Promise<string> {
  const proc = Bun.spawn(["bash", "-c", command], {
    cwd: process.cwd(),
    stdout: "pipe",
    stderr: "pipe",
    env: { ...process.env, GIT_PAGER: "cat", PAGER: "cat" },
  });
  const timer = setTimeout(() => proc.kill(), timeoutS * 1000);
  const [out, err, code] = await Promise.all([
    new Response(proc.stdout).text(),
    new Response(proc.stderr).text(),
    proc.exited,
  ]);
  clearTimeout(timer);
  let result = out;
  if (err.trim()) result += (result ? "\n" : "") + `[stderr]\n${err}`;
  if (code !== 0) {
    result += `\n[exit code: ${code}]`;
    throw new Error(cap(result.trim()));
  }
  return cap(result.trim() || "(no output)");
}

