async function readWithTimeout(stream: ReadableStream<Uint8Array> | undefined, ms: number): Promise<string> {
  if (!stream) return "";
  try {
    return await Promise.race([
      new Response(stream).text(),
      new Promise<string>((res) => setTimeout(() => res(""), ms)),
    ]);
  } catch {
    return "";
  }
}

async function runBash(command: string, timeoutS: number): Promise<string> {
  // Run under setsid so the command gets its own process group: that lets us
  // kill the WHOLE tree (including anything it backgrounds with `&`) on timeout.
  // Without this, a `python -m http.server &` keeps running and holds the stdout
  // pipe open, hanging output capture forever.
  const proc = Bun.spawn(["setsid", "bash", "-c", command], {
    cwd: process.cwd(),
    stdout: "pipe",
    stderr: "pipe",
    env: { ...process.env, GIT_PAGER: "cat", PAGER: "cat" },
  });
  const pgid = proc.pid;
  const killTree = (sig: NodeJS.Signals) => {
    try {
      process.kill(-pgid, sig); // negative pid → whole process group
    } catch {
      try {
        proc.kill();
      } catch {
        // already gone
      }
    }
  };

  let timedOut = false;
  const timer = setTimeout(() => {
    timedOut = true;
    killTree("SIGKILL");
  }, timeoutS * 1000);

  // Wait for bash itself to return. For a foreground blocking command this only
  // resolves when the timeout kills it; for `cmd &` it resolves immediately.
  const code = await proc.exited;
  clearTimeout(timer);
  // Reap any lingering process group (e.g. a backgrounded server) so its pipes
  // close and the drain below can't hang.
  killTree("SIGKILL");

  const out = await readWithTimeout(proc.stdout, 2000);
  const err = await readWithTimeout(proc.stderr, 2000);

  if (timedOut) {
    let r = out;
    if (err.trim()) r += (r ? "\n" : "") + `[stderr]\n${err}`;
    throw new Error(
      cap(
        `command timed out after ${timeoutS}s and was killed (with any processes it started). Do not run blocking commands like dev servers or watchers in the foreground — start them with \`&\`, probe with curl, then kill them.\n${r}`.trim(),
      ),
    );
  }

  let result = out;
  if (err.trim()) result += (result ? "\n" : "") + `[stderr]\n${err}`;
  if (code !== 0) {
    result += `\n[exit code: ${code}]`;
    throw new Error(cap(result.trim()));
  }
  return cap(result.trim() || "(no output)");
}

